def word_counts(text):
    counts = {}
    for w in text.lower().split():
        counts[w] = counts.get(w, 0) + 1
    return counts

def kg_per_crop(harvests):
    t = {}
    for h in harvests:
        t[h["crop"]] = t.get(h["crop"], 0) + h["kg"]
    return t

SW = {"water": "maji", "good": "nzuri", "food": "chakula", "school": "shule", "friend": "rafiki", "thank": "asante"}


def translate(sentence):
    return " ".join(SW.get(w.lower(), w) for w in sentence.split())
